func Contains[T comparable](s []T, v T) bool {
	for _, x := range s {
		if x == v { // comparable permits ==
			return true
		}
	}
	return false
}

func Keys[K comparable, V any](m map[K]V) []K {
	out := make([]K, 0, len(m)) // pre-size to avoid reallocations
	for k := range m {
		out = append(out, k)    // collect each key
	}
	return out
}
